import "server-only";
import { db } from "@/lib/db";

export async function categoryOptions() {
  const cats = await db.category.findMany({ include: { parent: { select: { name: true } } }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] });
  return cats
    .map((c) => ({ id: c.id, name: c.name, parentName: c.parent?.name ?? null }))
    .sort((a, b) => (a.parentName ?? a.name).localeCompare(b.parentName ?? b.name) || (a.parentName ? 1 : -1));
}
